from collections import deque
def comps(g,val=1):
    seen=[[False]*len(g[0]) for _ in g]; out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==val and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==val and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(cells)
    return out
