def variant(filled_fill, fill_overwrite_2, block_overwrite_2, keep_nonzero_lines=False):
    def f(i):
        i=np.array(i); h,w=i.shape; out=i.copy()
        HL,vL=detect(i)
        comps=[]
        seen=[[False]*w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if i[r][c]==3 and not seen[r][c]:
                    st=[(r,c)]; seen[r][c]=True; comp=[]
                    while st:
                        y,x=st.pop(); comp.append((y,x))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and i[ny][nx]==3 and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                    comps.append(comp)
        # fill direction
        if HL: vert=True; others=HL
        else: vert=False; others=vL
        for comp in comps:
            rs=[y for y,x in comp]; cs=[x for y,x in comp]
            cr,cc=(min(rs)+max(rs))//2,(min(cs)+max(cs))//2
            # fill: perpendicular line through center, skip non-zero? controlled by flags
            for r in range(h):
                v=out[r][cc]
                if v==2 and keep_nonzero_lines: continue
                if v!=2: out[r][cc]=1
            for c in range(w):
                v=out[cr][c]
                if v==2 and keep_nonzero_lines: continue
                if v!=2: out[cr][c]=1
            isH=bool(HL)
            for line in others:
                if isH:
                    rr,ccc=line[0],cc
                else:
                    rr,ccc=cr,line[1]
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        r_,c_=rr+dr,ccc+dc
                        if 0<=r_<h and 0<=c_<w:
                            v=out[r_][c_]
                            if v==2 and keep_nonzero_lines or (v==2 and not block_overwrite_2): continue
                            out[r_][c_]=1
        return out.tolist()
    return f

