    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
for p in ['1','2','3','4']:
    i=np.array(G[f'Demo pair {p} input']); o=np.array(G[f'Demo pair {p} output'])
    # detect lines: maximal runs of 2s length>=4
    HL=[]; VL=[]
    for r in range(i.shape[0]):
        c=0
        while c<i.shape[1]:
            if i[r][c]==2: s=c
            while c<i.shape[1] and i[r][c]==2: c+=1
            if c-s>=4: HL.append((r,s,c))
    for c in range(i.shape[1]):
        r=0
        while r<i.shape[0]:
            if i[r][c]==2: s=r
            while r<i.shape[0] and i[r][c]==2: r+=1
            if r-s>=4: VL.append((c,s,r))
    B=[]
    seen=set()
    for r in range(i.shape[0]):
        for c in range(i.shape[1]):
            if i[r][c]==3 and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<i.shape[0] and 0<=nx<i.shape[1] and i[ny][nx]==3: st.append((ny,nx))
                rs=[y for y,x in comp]; cs=[x for y,x in comp]
                if max(rs)-min(rs)<=2 and max(cs)-min(cs)<=2:
                    B.append(((min(rs)+max(rs))//2,(min(cs)+max(cs))//2))
    ch,i2=i.shape[0],i.shape[1]
    painted=[]
    for r in range(ch):
        for c in range(i2):
            if o[r][c]!=i[r][c]: painted.append((r,c,int(i[r][c]),int(o[r][c])))
    print('--- pair',p)
    print('  boxes',B,'HL',HL,'VL',VL)
    print('  painted:',len(painted))
    # characterize painted cells: which columns among HL? rows among VL?
    hrows={x for x,y,z in HL}; vcols={x for x,y,z in VL}
    ps=set((r,c) for r,c,a,b in painted)
    print('  painted on HL rows:',ps & {(r,0) for r in hrows}.pop().__class__ if False else any(r in hrows for r,c in ps),'count=',sum(1 for r,c in ps if r in hrows))
    print('  painted on VL cols:',any(c in vcols for r,c in ps),'count=',sum(1 for r,c in ps if c in vcols))

